import { Plugin } from '@servicenow/sdk-build-core'
import { Project } from '../../src'

describe('Dynamic coalescing', () => {
    test('Dynamic coalesce strategy that parses a JSON column', async () => {
        const project = new Project()
        project.getPlugins().prepend(
            Plugin.create({
                name: 'TestPlugin',
                records: {
                    test_table: {
                        coalesce: (props) =>
                            props.transform(({ $ }) => ({
                                field_a: $.map((v) => v.asString().parseJson().asObject().get('hello')),
                                field_b: $,
                            })),
                    },
                },
            })
        )

        const id = project.registerCoalesceId('test_table', { field_a: 'abc', field_b: 'xyz' })
        const file = project.addFile({
            path: 'test.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['ignore'],
    table: 'test_table',
    data: {
        field_a: "{ hello: 'abc', world: 'def' }",
        field_b: 'xyz',
    },
})
`,
        })

        const record = (await file.getRecords()).get('test_table', id)
        expect(record).toBeDefined()
        expect(project.getKeys().getValue()).toMatchObject({
            composite: [
                {
                    table: 'test_table',
                    id,
                    key: {
                        field_a: 'abc',
                        field_b: 'xyz',
                    },
                },
            ],
        })

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `<?xml version="1.0"?>
<record_update>
    <test_table action="INSERT_OR_UPDATE">
        <sys_id>00000</sys_id>
        <field_a>{ "hello": "abc", "world": "changed" }</field_a>
        <field_b>xyz</field_b>
    </test_table>
</record_update>`,
        })

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0]).toStrictEqual(file)
        expect(file.getContent()).toBe(`import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['ignore'],
    table: 'test_table',
    data: {
        field_a: '{ "hello": "abc", "world": "changed" }',
        field_b: 'xyz',
    },
})
`)
    })
})
